pub fn term_set(terms: &[Term]) -> std::collections::HashSet<String> {
    terms.iter().map(|t| t.term.to_lowercase()).collect()
}

/// O(1) lookup index from terminology.csv and lexicon.csv (S-02).
pub fn term_index(residual_dir: &Path) -> Result<std::collections::HashSet<String>> {
    let mut set = term_set(&load(residual_dir)?);
    for t in crate::storage::format::read_lexicon(residual_dir)? {
        if !t.term.is_empty() {
            set.insert(t.term.to_lowercase());
        }
        for alias in t.aliases.split('|') {
            let alias = alias.trim();
            if !alias.is_empty() {
                set.insert(alias.to_lowercase());
            }
        }
    }
    Ok(set)
}

