/// Add a residue mapping (force × component).
Residue {
    #[arg(long)] force_id: String,
    #[arg(long)] component_id: String,
    #[arg(long, default_value = "proposed")] status: String,
    #[arg(long, default_value = "")] notes: String,
},
/// Add a purpose force. Process: whole-system-residue first — record outcomes.

    Iterations,
    Residues,
}

use anyhow::{bail, Result};
use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::Path;

pub fn write_residues(residual_dir: &Path, residues: &[Residue]) -> Result<()> {
    let path = residual_dir.join("residues.csv");
    let id_to_short = force_shortname_lookup(residual_dir)?;
    let mut components: Vec<String> = residues
        .iter()
        .map(|r| r.component_id.clone())
        .filter(|c| !c.is_empty())
        .collect::<HashSet<_>>()
        .into_iter()
        .collect();
    components.sort();
    let mut rows: BTreeMap<String, HashMap<String, (String, String)>> = BTreeMap::new();
    for r in residues {
        let short = id_to_short
            .get(&r.force_id)
            .cloned()
            .unwrap_or_else(|| r.force_id.clone());
        rows.entry(short)
            .or_default()
            .insert(r.component_id.clone(), (r.status.clone(), r.notes.clone()));
    }
    let mut buf = RESIDUES_MATRIX_FORCE_COL.to_string();
    for c in &components {
        buf.push(',');
        buf.push_str(c);
    }
    buf.push('\n');
    for (short, cells) in &rows {
        let mut row = vec![short.as_str()];
        for comp in &components {
            let cell = cells
                .get(comp)
                .map(|(s, n)| encode_residue_cell(s, n))
                .unwrap_or_default();
            row.push(cell.as_str());
        }
        let mut encoded = Vec::new();
        {
            let mut wtr = csv::WriterBuilder::new()
                .has_headers(false)
                .from_writer(&mut encoded);
            wtr.write_record(&row)?;
            wtr.flush()?;
        }
        buf.push_str(std::str::from_utf8(&encoded)?);
    }
    std::fs::write(path, buf)?;
    Ok(())
}

fn force_shortname_lookup(residual_dir: &Path) -> Result<HashMap<String, String>> {
    let mut id_to_short = HashMap::new();
    for f in read_forces(residual_dir)? {
        id_to_short.insert(
            f.id.clone(),
            if f.shortname.is_empty() { f.id.clone() } else { f.shortname.clone() },
        );
    }
    for s in crate::storage::stressors::load(residual_dir)? {
        id_to_short.entry(s.id.clone()).or_insert_with(|| s.id.clone());
    }
    for p in crate::storage::purposes::load(residual_dir)? {
        id_to_short.entry(p.id.clone()).or_insert_with(|| p.id.clone());
    }
    Ok(id_to_short)
}

fn shortname_to_force_id(residual_dir: &Path) -> Result<HashMap<String, String>> {
    let mut short_to_id = HashMap::new();
    for f in read_forces(residual_dir)? {
        if !f.shortname.is_empty() {
            short_to_id.insert(f.shortname.clone(), f.id.clone());
        }
        short_to_id.insert(f.id.clone(), f.id.clone());
    }
    for s in crate::storage::stressors::load(residual_dir)? {
        short_to_id.entry(s.id.clone()).or_insert_with(|| s.id.clone());
    }
    for p in crate::storage::purposes::load(residual_dir)? {
        short_to_id.entry(p.id.clone()).or_insert_with(|| p.id.clone());
    }
    Ok(short_to_id)
}

fn encode_residue_cell(status: &str, notes: &str) -> String {
    if notes.is_empty() {
        status.to_string()
    } else {
        format!("{status}|{notes}")
    }
}

fn decode_residue_cell(cell: &str) -> (String, String) {
    if let Some((status, notes)) = cell.split_once('|') {
        (status.trim().to_string(), notes.trim().to_string())
    } else {
        (cell.trim().to_string(), String::new())
    }
}

pub fn read_residues(residual_dir: &Path) -> Result<Vec<Residue>> {
    let path = residual_dir.join("residues.csv");
    if !path.exists() {
        return Ok(vec![]);
    }
    let content = std::fs::read_to_string(&path)?;
    if content.trim().is_empty() {
        return Ok(vec![]);
    }
    let mut rdr = csv::ReaderBuilder::new()
        .has_headers(true)
        .from_reader(content.as_bytes());
    let headers: Vec<String> = rdr.headers()?.iter().map(|s| s.to_string()).collect();
    if headers.first().map(|h| h.as_str()) == Some(RESIDUES_MATRIX_FORCE_COL) {
        let short_to_id = shortname_to_force_id(residual_dir)?;
        let components: Vec<String> = headers.iter().skip(1).cloned().collect();
        let mut out = Vec::new();
        let mut n: u32 = 0;
        for rec in rdr.records() {
            let rec = rec?;
            let short = rec.get(0).unwrap_or("").trim();
            if short.is_empty() {
                continue;
            }
            let force_id = short_to_id
                .get(short)
                .cloned()
                .unwrap_or_else(|| short.to_string());
            for (col_idx, comp) in components.iter().enumerate() {
                let cell = rec.get(col_idx + 1).unwrap_or("").trim();
                if cell.is_empty() {
                    continue;
                }
                n += 1;
                let (status, notes) = decode_residue_cell(cell);
                out.push(Residue {
                    id: format!("R-{n:02}"),
                    force_id: force_id.clone(),
                    component_id: comp.clone(),
                    status,
                    notes,
                });
            }
        }
        Ok(out)
    } else if headers.first().map(|h| h.as_str()) == Some("id") {
        let mut out = Vec::new();
        for rec in rdr.records() {
            let rec = rec?;
            out.push(Residue {
                id: rec.get(0).unwrap_or("").to_string(),
                force_id: rec.get(1).unwrap_or("").to_string(),
                component_id: rec.get(2).unwrap_or("").to_string(),
                status: rec.get(3).unwrap_or("").to_string(),
                notes: rec.get(4).unwrap_or("").to_string(),
            });
        }
        Ok(out)
    } else {
        bail!("unrecognized residues.csv header: {:?}", headers);
    }
}

pub fn format_residues_matrix(residual_dir: &Path) -> Result<String> {
    let path = residual_dir.join("residues.csv");
    if !path.exists() {
        return Ok(String::new());
    }
    Ok(std::fs::read_to_string(&path)?)
}

