pub fn check_links(cfg: &Config) -> Result<Vec<LinkViolation>> {
    let stressors = crate::storage::stressors::load(&cfg.residual_dir)?;
    let purposes = crate::storage::purposes::load(&cfg.residual_dir)?;
    let attractors = crate::storage::attractors::load(&cfg.residual_dir)?;
    let forces = crate::storage::format::read_forces(&cfg.residual_dir)?;
    let residues = crate::storage::format::read_residues(&cfg.residual_dir)?;
    let registry = crate::structure::definition::components::load(&cfg.residual_dir)?;
    let attractor_ids: std::collections::HashSet<String> = attractors.iter().map(|a| a.id.clone()).collect();
    let mut force_ids = std::collections::HashSet::new();
    for s in &stressors { force_ids.insert(s.id.clone()); }
    for p in &purposes { force_ids.insert(p.id.clone()); }
    for f in &forces { force_ids.insert(f.id.clone()); }
    let component_names: std::collections::HashSet<String> = registry.iter().map(|c| c.name.clone()).collect();
    let mut violations = Vec::new();
    for stressor in &stressors {
        if !stressor.attractor_id.is_empty() && !attractor_ids.contains(&stressor.attractor_id) {
            violations.push(LinkViolation { source: "stressor".into(), id: stressor.id.clone(), message: format!("missing attractor '{}'", stressor.attractor_id) });
        }
    }
    for purpose in &purposes {
        if !purpose.attractor_id.is_empty() && !attractor_ids.contains(&purpose.attractor_id) {
            violations.push(LinkViolation { source: "purpose".into(), id: purpose.id.clone(), message: format!("missing attractor '{}'", purpose.attractor_id) });
        }
    }
    for force in &forces {
        if !force.attractor_id.is_empty() && !attractor_ids.contains(&force.attractor_id) {
            violations.push(LinkViolation { source: "force".into(), id: force.id.clone(), message: format!("missing attractor '{}'", force.attractor_id) });
        }
    }
    for residue in &residues {
        if !residue.force_id.is_empty() && !force_ids.contains(&residue.force_id) {
            violations.push(LinkViolation { source: "residue".into(), id: residue.id.clone(), message: format!("force_id '{}' not found", residue.force_id) });
        }
        if !residue.component_id.is_empty() && !component_names.contains(&residue.component_id) {
            violations.push(LinkViolation { source: "residue".into(), id: residue.id.clone(), message: format!("component_id '{}' not found in components.csv", residue.component_id) });
        }
    }
    Ok(violations)
}

