f = Path('src/storage/format.rs')
text = f.read_text()
text = text.replace('use anyhow::Result;\nuse std::path::Path;', 'use anyhow::Result;\nuse std::collections::{BTreeMap, BTreeSet};\nuse std::path::Path;')
text = text.replace('const RESIDUES_HEADER: &str = "id,force_id,component_id,status,notes";', 'const RESIDUES_MATRIX_FORCE_COL: &str = "force";')
matrix_impl = r'''
fn parse_residue_cell(cell: &str) -> (String, String) {
    if let Some((status, notes)) = cell.split_once('|') { (status.trim().to_string(), notes.trim().to_string()) }
    else { (cell.trim().to_string(), String::new()) }
}
fn format_residue_cell(status: &str, notes: &str) -> String { if notes.is_empty() { status.to_string() } else { format!("{status}|{notes}") } }
fn residues_is_matrix_header(header: &str) -> bool { header.split(',').next().map(|c| c.trim().eq_ignore_ascii_case(RESIDUES_MATRIX_FORCE_COL)).unwrap_or(false) }
fn residues_to_rows(residues: &[Residue]) -> (Vec<String>, BTreeMap<String, BTreeMap<String, (String, String)>>) {
    let mut components = BTreeSet::new(); let mut cells = BTreeMap::new();
    for r in residues { if r.force_id.is_empty()||r.component_id.is_empty(){continue}
        components.insert(r.component_id.clone()); cells.entry(r.force_id.clone()).or_insert_with(BTreeMap::new).insert(r.component_id.clone(), (r.status.clone(), r.notes.clone())); }
    (components.into_iter().collect(), cells)
}
fn render_residues_matrix(residues: &[Residue]) -> String {
    let (components, cells) = residues_to_rows(residues); let mut buf = RESIDUES_MATRIX_FORCE_COL.to_string();
    for c in &components { buf.push(','); buf.push_str(c); } buf.push('\n');
    for force_id in cells.keys() { let fc = cells.get(force_id).unwrap(); let mut row = vec![force_id.as_str()]; let mut vals = Vec::new();
        for c in &components { vals.push(fc.get(c).map(|(s,n)| format_residue_cell(s,n)).unwrap_or_default()); }
        for v in &vals { row.push(v.as_str()); }
        let mut out = Vec::new(); { let mut w = csv::WriterBuilder::new().has_headers(false).from_writer(&mut out); w.write_record(&row).unwrap(); w.flush().unwrap(); }
        buf.push_str(std::str::from_utf8(&out).unwrap()); }
    buf
}
pub fn format_residues_matrix(residual_dir: &Path) -> Result<String> { Ok(render_residues_matrix(&read_residues(residual_dir)?)) }
pub fn write_residues(residual_dir: &Path, residues: &[Residue]) -> Result<()> { std::fs::write(residual_dir.join("residues.csv"), render_residues_matrix(residues))?; Ok(()) }
pub fn read_residues(residual_dir: &Path) -> Result<Vec<Residue>> {
    let path = residual_dir.join("residues.csv"); if !path.exists() { return Ok(vec![]); }
    let text = std::fs::read_to_string(&path)?; let mut lines = text.lines(); let header = lines.next().unwrap_or("");
    if header.trim().is_empty() { return Ok(vec![]); }
    if residues_is_matrix_header(header) { return read_residues_matrix(header, lines); }
    read_residues_legacy(&path)
}
fn read_residues_matrix<'a,I>(header:&str,rows:I)->Result<Vec<Residue>> where I:Iterator<Item=&'a str> {
    let components:Vec<String>=header.split(',').skip(1).map(|s|s.trim().to_string()).filter(|s|!s.is_empty()).collect();
    let mut out=Vec::new(); let mut id_n=0u32;
    for line in rows { if line.trim().is_empty(){continue}
        let mut rdr=csv::ReaderBuilder::new().has_headers(false).from_reader(line.as_bytes());
        let rec=rdr.records().next().transpose()?.unwrap_or_default(); let force_id=rec.get(0).unwrap_or("").trim().to_string();
        if force_id.is_empty(){continue}
        for (i,comp) in components.iter().enumerate(){ let cell=rec.get(i+1).unwrap_or("").trim(); if cell.is_empty(){continue}
            id_n+=1; let (status,notes)=parse_residue_cell(cell);
            out.push(Residue{id:format!("R-{id_n:02}"),force_id:force_id.clone(),component_id:comp.clone(),status,notes}); } }
